CREATE OR REPLACE FUNCTION public.finance_audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb:=to_jsonb(NEW); o jsonb; row_branch text; BEGIN
IF TG_OP='UPDATE' THEN o:=to_jsonb(OLD); IF n=o THEN RETURN NEW; END IF; END IF;
row_branch:=n->>'branch';
IF row_branch IS NULL AND n->>'budget_id' IS NOT NULL THEN SELECT branch::text INTO row_branch FROM public.budgets WHERE id=(n->>'budget_id')::uuid; END IF;
IF row_branch IS NULL AND n->>'statement_id' IS NOT NULL THEN SELECT branch::text INTO row_branch FROM public.bank_statements WHERE id=(n->>'statement_id')::uuid; END IF;
IF row_branch IS NULL AND n->>'run_id' IS NOT NULL THEN SELECT branch::text INTO row_branch FROM public.payroll_runs WHERE id=(n->>'run_id')::uuid; END IF;
IF row_branch IS NULL AND n->>'period_id' IS NOT NULL THEN SELECT branch::text INTO row_branch FROM public.fin_month_periods WHERE id=(n->>'period_id')::uuid; END IF;
IF row_branch IS NULL AND n->>'request_id' IS NOT NULL THEN IF n->>'request_type' IN ('purchase_request','purchase_requests') THEN SELECT branch::text INTO row_branch FROM public.purchase_requests WHERE id=(n->>'request_id')::uuid; ELSIF n->>'request_type'='budgets' THEN SELECT branch::text INTO row_branch FROM public.budgets WHERE id=(n->>'request_id')::uuid; ELSE SELECT b.branch::text INTO row_branch FROM public.budget_adjustments a JOIN public.budgets b ON b.id=a.budget_id WHERE a.id=(n->>'request_id')::uuid; END IF; END IF;
INSERT INTO public.audit_log(actor_id,action,entity,entity_id,details) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,n->>'id',jsonb_build_object('old',o,'new',n,'branch',row_branch)); RETURN NEW; END $$;
DO $$ DECLARE t text; trg record; BEGIN FOREACH t IN ARRAY ARRAY['finance_entries','expense_claims','purchase_requests','budgets','budget_lines','budget_adjustments','budget_revisions','finance_approval_decisions','fin_month_periods','fin_month_lines','bank_accounts','bank_statements','bank_transactions','payroll_runs','payroll_lines'] LOOP
FOR trg IN SELECT tgname FROM pg_trigger g JOIN pg_class c ON c.oid=g.tgrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace JOIN pg_proc p ON p.oid=g.tgfoid WHERE ns.nspname='public' AND c.relname=t AND NOT g.tgisinternal AND p.proname IN ('gov_log_audit_event','finance_audit_change','audit_sensitive_change') LOOP EXECUTE format('DROP TRIGGER %I ON public.%I',trg.tgname,t); END LOOP;
EXECUTE format('CREATE TRIGGER finance_audit_change AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.finance_audit_change()',t); END LOOP; END $$;
CREATE POLICY finance_audit_read ON public.audit_log FOR SELECT TO authenticated USING ((public.finance_is_reviewer(auth.uid()) OR public.finance_is_leader(auth.uid())) AND entity IN ('finance_entries','expense_claims','purchase_requests','budgets','budget_lines','budget_adjustments','budget_revisions','finance_approval_decisions','fin_month_periods','fin_month_lines','bank_accounts','bank_statements','bank_transactions','payroll_runs','payroll_lines') AND (public.is_head_office(auth.uid()) OR details->>'branch'=public.my_branch()::text));
CREATE POLICY finance_audit_branch ON public.audit_log AS RESTRICTIVE FOR SELECT TO authenticated USING (entity NOT IN ('finance_entries','expense_claims','purchase_requests','budgets','budget_lines','budget_adjustments','budget_revisions','finance_approval_decisions','fin_month_periods','fin_month_lines','bank_accounts','bank_statements','bank_transactions','payroll_runs','payroll_lines') OR public.is_head_office(auth.uid()) OR details->>'branch'=public.my_branch()::text);
DO $$ DECLARE t text; parent text; col text; BEGIN FOR t,parent,col IN VALUES ('bank_transactions','bank_statements','statement_id'),('payroll_lines','payroll_runs','run_id'),('budget_adjustments','budgets','budget_id'),('budget_lines','budgets','budget_id'),('budget_revisions','budgets','budget_id'),('fin_month_lines','fin_month_periods','period_id') LOOP
EXECUTE format('CREATE POLICY finance_parent_branch ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.%I p WHERE p.id=%I AND (public.is_head_office(auth.uid()) OR p.branch IS NULL OR p.branch=public.my_branch()))) WITH CHECK (EXISTS(SELECT 1 FROM public.%I p WHERE p.id=%I AND (public.is_head_office(auth.uid()) OR p.branch=public.my_branch() OR (p.branch IS NULL AND public.my_branch() IS NULL))))',t,parent,col,parent,col); END LOOP; END $$;
CREATE POLICY finance_decision_branch ON public.finance_approval_decisions AS RESTRICTIVE FOR SELECT TO authenticated USING (public.is_head_office(auth.uid()) OR EXISTS(SELECT 1 FROM public.purchase_requests p WHERE p.id=request_id AND request_type IN ('purchase_request','purchase_requests') AND (p.branch IS NULL OR p.branch=public.my_branch())) OR EXISTS(SELECT 1 FROM public.budgets b WHERE b.id=request_id AND request_type='budgets' AND (b.branch IS NULL OR b.branch=public.my_branch())) OR EXISTS(SELECT 1 FROM public.budget_adjustments a JOIN public.budgets b ON b.id=a.budget_id WHERE a.id=request_id AND request_type='budget_adjustments' AND (b.branch IS NULL OR b.branch=public.my_branch())));
CREATE OR REPLACE VIEW public.finance_movements WITH (security_invoker=true) AS
SELECT id,entry_date AS movement_date,department_slug,branch,kind,category,COALESCE(amount,0) AS amount FROM public.finance_entries WHERE status IN ('approved','completed')
UNION ALL SELECT id,COALESCE(paid_at,created_at)::date,department_slug,branch,'expense_claim',claim_type,-amount FROM public.expense_claims WHERE status='paid' AND ledger_entry_id IS NULL
UNION ALL SELECT l.id,COALESCE(r.paid_at,r.period_end::timestamptz)::date,l.department_slug,r.branch,'payroll',l.role_title,-l.net_amount FROM public.payroll_lines l JOIN public.payroll_runs r ON r.id=l.run_id WHERE l.payment_status='paid' AND l.ledger_entry_id IS NULL;
GRANT SELECT ON public.finance_movements TO authenticated;
GRANT ALL ON public.finance_movements TO service_role;
CREATE OR REPLACE FUNCTION public.get_finance_summary(_months integer DEFAULT 12) RETURNS TABLE(total_income numeric,total_expense numeric,cash_position numeric,income_this_month numeric,expense_this_month numeric,giving_today numeric,giving_this_month numeric,outstanding_payments numeric,pending_approvals bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH m AS (SELECT * FROM public.finance_movements WHERE movement_date>=current_date-make_interval(months=>_months)),c AS (SELECT COALESCE(sum(current_balance),0) cash FROM public.bank_accounts WHERE is_active AND archived_at IS NULL),p AS (SELECT COALESCE(sum(COALESCE(amount_actual,amount_estimated)) FILTER(WHERE status IN ('senior_pastor_approved','ordered','received')),0) outstanding,count(*) FILTER(WHERE status IN ('submitted','finance_approved','chair_approved')) pending FROM public.purchase_requests WHERE archived_at IS NULL AND payment_status<>'paid' AND status NOT IN ('rejected','cancelled','returned')),e AS (SELECT COALESCE(sum(amount) FILTER(WHERE status='senior_pastor_approved'),0) outstanding,count(*) FILTER(WHERE status IN ('pending','chair_approved')) pending FROM public.expense_claims WHERE archived_at IS NULL AND status NOT IN ('paid','rejected'))
SELECT COALESCE(sum(m.amount) FILTER(WHERE m.amount>0),0),COALESCE(-sum(m.amount) FILTER(WHERE m.amount<0),0),c.cash,COALESCE(sum(m.amount) FILTER(WHERE m.amount>0 AND date_trunc('month',m.movement_date)=date_trunc('month',current_date)),0),COALESCE(-sum(m.amount) FILTER(WHERE m.amount<0 AND date_trunc('month',m.movement_date)=date_trunc('month',current_date)),0),COALESCE(sum(m.amount) FILTER(WHERE m.movement_date=current_date AND m.kind IN ('sunday_contribution','tithe','offering','first_fruits','seed','pledge')),0),COALESCE(sum(m.amount) FILTER(WHERE date_trunc('month',m.movement_date)=date_trunc('month',current_date) AND m.kind IN ('sunday_contribution','tithe','offering','first_fruits','seed','pledge')),0),p.outstanding+e.outstanding,p.pending+e.pending FROM c CROSS JOIN p CROSS JOIN e LEFT JOIN m ON true GROUP BY c.cash,p.outstanding,e.outstanding,p.pending,e.pending $$;
CREATE OR REPLACE FUNCTION public.get_financial_trend(_months integer DEFAULT 6) RETURNS TABLE(period text,income numeric,expense numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT to_char(d,'YYYY-MM'),COALESCE(sum(m.amount) FILTER(WHERE m.amount>0),0),COALESCE(-sum(m.amount) FILTER(WHERE m.amount<0),0) FROM generate_series(date_trunc('month',current_date)-make_interval(months=>GREATEST(_months-1,0)),date_trunc('month',current_date),interval '1 month') d LEFT JOIN public.finance_movements m ON date_trunc('month',m.movement_date)=d GROUP BY d ORDER BY d $$;
CREATE OR REPLACE FUNCTION public.get_budget_positions() RETURNS TABLE(budget_id uuid,reference_number text,name text,department_slug text,branch public.branch,budget_type text,period_label text,category text,fiscal_year integer,period_start date,period_end date,status text,allocated numeric,spent numeric,committed numeric,pending numeric,available numeric,utilisation_pct numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH pr AS (SELECT budget_id,COALESCE(sum(COALESCE(amount_actual,amount_estimated)) FILTER(WHERE payment_status='paid'),0) spent,COALESCE(sum(COALESCE(amount_actual,amount_estimated)) FILTER(WHERE payment_status<>'paid' AND status IN ('senior_pastor_approved','ordered','received')),0) committed,COALESCE(sum(amount_estimated) FILTER(WHERE payment_status<>'paid' AND status IN ('draft','submitted','returned','finance_approved','chair_approved')),0) pending FROM public.purchase_requests WHERE status NOT IN ('rejected','cancelled') GROUP BY budget_id),b AS (SELECT *,CASE WHEN status IN ('approved','partially_approved','active','locked') THEN COALESCE(approved_amount,total_amount,0) ELSE 0 END allocation FROM public.budgets WHERE archived_at IS NULL)
SELECT b.id,b.reference_number,b.name,b.department_slug,b.branch,b.budget_type,b.period_label,b.category,b.fiscal_year,b.period_start,b.period_end,b.status,b.allocation,COALESCE(pr.spent,0),COALESCE(pr.committed,0),COALESCE(pr.pending,0),b.allocation-COALESCE(pr.spent,0)-COALESCE(pr.committed,0),CASE WHEN b.allocation>0 THEN round((COALESCE(pr.spent,0)+COALESCE(pr.committed,0))/b.allocation*100,1) ELSE 0 END FROM b LEFT JOIN pr ON pr.budget_id=b.id $$;
CREATE OR REPLACE FUNCTION public.get_budget_utilisation(_fiscal_year integer DEFAULT NULL) RETURNS TABLE(budget_id uuid,name text,department_slug text,branch public.branch,fiscal_year integer,planned numeric,actual numeric,committed numeric,remaining numeric,variance numeric,utilisation_pct numeric,budget_type text,status text) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT p.budget_id,p.name,p.department_slug,p.branch,p.fiscal_year,p.allocated,p.spent,p.committed,p.available,p.allocated-p.spent,p.utilisation_pct,p.budget_type,p.status FROM public.get_budget_positions() p WHERE _fiscal_year IS NULL OR p.fiscal_year=_fiscal_year $$;
CREATE OR REPLACE FUNCTION public.get_church_finance_position() RETURNS TABLE(total_cash numeric,reserved numeric,allocated numeric,committed numeric,spent numeric,pending numeric,unallocated numeric,available numeric) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
WITH c AS (SELECT COALESCE(sum(current_balance),0) cash,COALESCE(sum(reserved_balance),0) reserved FROM public.bank_accounts WHERE is_active AND archived_at IS NULL),p AS (SELECT COALESCE(sum(allocated),0) allocation,COALESCE(sum(available),0) remaining FROM public.get_budget_positions() WHERE status IN ('approved','partially_approved','active','locked')),pr AS (SELECT COALESCE(sum(COALESCE(amount_actual,amount_estimated)) FILTER(WHERE payment_status<>'paid' AND status IN ('senior_pastor_approved','ordered','received')),0) committed,COALESCE(sum(amount_estimated) FILTER(WHERE status IN ('submitted','returned','finance_approved','chair_approved')),0) pending FROM public.purchase_requests WHERE status NOT IN ('rejected','cancelled') AND archived_at IS NULL),cl AS (SELECT COALESCE(sum(amount) FILTER(WHERE status='senior_pastor_approved'),0) committed,COALESCE(sum(amount) FILTER(WHERE status IN ('pending','chair_approved')),0) pending FROM public.expense_claims WHERE archived_at IS NULL),m AS (SELECT COALESCE(-sum(amount) FILTER(WHERE amount<0),0) spent FROM public.finance_movements)
SELECT c.cash,c.reserved,p.allocation,pr.committed+cl.committed,m.spent,pr.pending+cl.pending,c.cash-c.reserved-p.remaining-cl.committed,c.cash-c.reserved-pr.committed-cl.committed FROM c,p,pr,cl,m $$;
REVOKE ALL ON FUNCTION public.get_finance_summary(integer),public.get_financial_trend(integer),public.get_budget_positions(),public.get_budget_utilisation(integer),public.get_church_finance_position() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_finance_summary(integer),public.get_financial_trend(integer),public.get_budget_positions(),public.get_budget_utilisation(integer),public.get_church_finance_position() TO authenticated;